                if(eliminado)
                    System.out.println("Cliente Eliminado: " + cliente);
                else
                    System.out.println("Cliente NO eliminado: " + cliente);
            }
            case 6 -> { 
                System.out.println("Hasta pronto!");
                salir = true;
            }
            default -> System.out.println("Opcion no reconocida: " + opcion);
        }
        return salir;
    }

