methods.fromObjectIdToHexString:
{
        return arg.data.map(obj => {
            const newObj = { ...obj };
            Object.keys(newObj).forEach(key => {
                if (key.includes('_id') && newObj[key] instanceof ObjectId) {
                    newObj[key] = newObj[key].toString();
                }
            });
            return newObj;
        });
    }

